<script setup>
import { ref, watch } from 'vue'
const props = defineProps({ error: String, session: Object })
const emit = defineEmits(['save', 'cancel', 'dirty'])
const form = ref({ verdict: '', assistanceLevel: '', masteryPercent: 50, minutes: '', errorTypes: [], note: '' })
if (props.session) form.value = { ...props.session, masteryPercent: props.session.masteryPercent ?? props.session.selfRating * 20, minutes: props.session.durationSeconds == null ? '' : props.session.durationSeconds / 60, errorTypes: [...(props.session.errorTypes ?? [])] }
const initialForm = JSON.stringify(form.value)
watch(form, () => emit('dirty', JSON.stringify(form.value) !== initialForm), { deep: true })
</script>
<template>
<form class="practice-form" @submit.prevent="emit('save', { ...form, selfRating: Math.max(1, Math.ceil(form.masteryPercent / 20)) })">
<p class="form-eyebrow">AlgoFlow · 训练记录</p><h1 id="record-title" tabindex="-1">{{ session ? '编辑训练记录' : '完成本次训练' }}</h1><p>结果由你自报，不是 OJ 官方判题。</p>
<fieldset><legend>训练结果</legend><div class="result-options"><label v-for="option in [{value:'AC',label:'AC'},{value:'WA',label:'WA'},{value:'TLE',label:'TLE'},{value:'UNFINISHED',label:'未完成'}]" :key="option.value"><input v-model="form.verdict" type="radio" name="verdict" :value="option.value" required />{{ option.label }}</label></div></fieldset>
<fieldset><legend>完成方式</legend><label v-for="option in [{value:'INDEPENDENT',label:'独立完成 / 尝试'},{value:'HINT',label:'查看提示后完成 / 尝试'},{value:'SOLUTION',label:'参考题解后完成 / 尝试'}]" :key="option.value"><input v-model="form.assistanceLevel" type="radio" name="assistance" :value="option.value" required />{{ option.label }}</label></fieldset>
<div class="rating-heading"><label for="rating">自评掌握程度</label><strong>{{ form.masteryPercent }}%</strong></div><input id="rating" v-model.number="form.masteryPercent" :style="{ '--mastery': form.masteryPercent + '%' }" type="range" min="0" max="100" step="1" /><div class="rating-scale"><span>不会</span><span>基本理解</span><span>熟练</span></div>
<label class="stack">耗时（分钟，可留空）<input v-model="form.minutes" type="number" min="0" max="10080" step="any" placeholder="本次训练用了多久？" /></label><details><summary>补充错因或笔记（选填）</summary><fieldset><legend>错误类型（可多选）</legend><div class="error-options"><label v-for="type in ['思路错误','边界错误','代码实现错误','复杂度超时','知识点不熟悉']" :key="type"><input v-model="form.errorTypes" type="checkbox" :value="type" />{{ type }}</label></div></fieldset><label class="stack">复盘笔记<textarea v-model="form.note" rows="4" maxlength="10000" placeholder="例如：二分边界更新方向错误……" /></label></details>
<p v-if="error" role="alert">{{ error }}</p><button class="primary-button" type="submit">保存本次训练</button><button class="secondary-button" type="button" @click="emit('cancel')">取消并返回详情</button>
</form>
</template>
<style scoped>
